ALTER TABLE "CustomerRecord" ADD COLUMN "userId" TEXT;
CREATE INDEX "CustomerRecord_businessId_userId_idx" ON "CustomerRecord"("businessId", "userId");
ALTER TABLE "CustomerRecord" ADD CONSTRAINT "CustomerRecord_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "ServiceRequest" ADD COLUMN "providerBusinessId" TEXT;
ALTER TABLE "ServiceRequest" ADD CONSTRAINT "ServiceRequest_providerBusinessId_fkey" FOREIGN KEY ("providerBusinessId") REFERENCES "Business"("id") ON DELETE SET NULL ON UPDATE CASCADE;
CREATE TABLE "CustomerConversation" ("id" TEXT NOT NULL, "customerId" TEXT NOT NULL, "businessId" TEXT NOT NULL, "serviceRequestId" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "CustomerConversation_pkey" PRIMARY KEY ("id"));
