CREATE INDEX "CustomerConversation_customerId_updatedAt_idx" ON "CustomerConversation"("customerId", "updatedAt");
CREATE INDEX "CustomerConversation_businessId_updatedAt_idx" ON "CustomerConversation"("businessId", "updatedAt");
ALTER TABLE "CustomerConversation" ADD CONSTRAINT "CustomerConversation_customerId_fkey" FOREIGN KEY ("customerId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "CustomerConversation" ADD CONSTRAINT "CustomerConversation_businessId_fkey" FOREIGN KEY ("businessId") REFERENCES "Business"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "CustomerConversation" ADD CONSTRAINT "CustomerConversation_serviceRequestId_fkey" FOREIGN KEY ("serviceRequestId") REFERENCES "ServiceRequest"("id") ON DELETE SET NULL ON UPDATE CASCADE;
CREATE TABLE "CustomerMessage" ("id" TEXT NOT NULL, "conversationId" TEXT NOT NULL, "senderId" TEXT NOT NULL, "body" TEXT NOT NULL, "readAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "CustomerMessage_pkey" PRIMARY KEY ("id"));
