ALTER TABLE "CustomerMessage" ADD CONSTRAINT "CustomerMessage_conversationId_fkey" FOREIGN KEY ("conversationId") REFERENCES "CustomerConversation"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "CustomerMessage" ADD CONSTRAINT "CustomerMessage_senderId_fkey" FOREIGN KEY ("senderId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
