UPDATE "CustomerRecord" AS c SET "userId" = u.id FROM "User" AS u WHERE u.role = 'CUSTOMER' AND c."userId" IS NULL AND c.phone = u.phone;
UPDATE "CustomerRecord" AS c SET "userId" = u.id FROM "User" AS u WHERE u.role = 'CUSTOMER' AND c."userId" IS NULL AND c.email IS NOT NULL AND lower(c.email) = lower(u.email) AND NOT EXISTS (SELECT 1 FROM "User" AS by_phone WHERE by_phone.role = 'CUSTOMER' AND by_phone.phone = c.phone);
CREATE INDEX "ServiceRequest_providerBusinessId_status_idx" ON "ServiceRequest"("providerBusinessId", "status");
CREATE UNIQUE INDEX "CustomerConversation_no_request_key" ON "CustomerConversation"("customerId", "businessId") WHERE "serviceRequestId" IS NULL;
